 private static T[] E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>().ToArray();
 private static bool Open(GameEngine g)=>P(g)is{}p&&p.Choices.Any(c=>c.Parameters.ContainsKey("zonghu-request"));
